package metatask

import (
	"encoding/json"
	"os"
	"testing"
)

// Three-engine byte-parity harness (acceptance criterion of the v1.2.1
// upgrade): on the SAME event set, this Go engine and the IDBots TS reference
// engine must produce byte-identical eventSetHash and settlement manifests.
//
// testdata/v121-ts-golden.json is generated by running the compiled TS engine
// (dist-electron/main/services/metatask/engine.js, algo version pinned by the
// fixture set) over the shared conformance fixture — see the golden's
// `source` field. Regenerate only from the same fixture (canonical sha256
// asserted below).

type tsGoldenEntry struct {
	ID                  string  `json:"id"`
	EventSetHash        string  `json:"eventSetHash"`
	BoundaryBlock       int64   `json:"boundaryBlock"`
	TaskComplete        bool    `json:"taskComplete"`
	SettlementCanonical *string `json:"settlementCanonical"`
	SettlementSha256    *string `json:"settlementSha256"`
}

type tsGolden struct {
	Source             string          `json:"source"`
	EngineAlgoVersion  string          `json:"engineAlgoVersion"`
	FixtureCanonSha256 string          `json:"fixtureCanonSha256"`
	Entries            []tsGoldenEntry `json:"entries"`
}

func TestV121TSParityEventSetHashAndManifest(t *testing.T) {
	set := loadConformanceSet(t)
	raw, err := os.ReadFile("testdata/v121-ts-golden.json")
	if err != nil {
		t.Fatalf("read TS golden: %v", err)
	}
	var golden tsGolden
	if err := json.Unmarshal(raw, &golden); err != nil {
		t.Fatalf("parse TS golden: %v", err)
	}
	if golden.FixtureCanonSha256 != conformanceCanonSHA256 {
		t.Fatalf("golden was generated from a different fixture (canon sha %s)", golden.FixtureCanonSha256)
	}
	if golden.EngineAlgoVersion != EngineAlgoVersionV121 {
		t.Fatalf("golden engineAlgoVersion=%s, want %s", golden.EngineAlgoVersion, EngineAlgoVersionV121)
	}
	byID := map[string]tsGoldenEntry{}
	for _, e := range golden.Entries {
		byID[e.ID] = e
	}
	ran := 0
	for _, v := range set.Vectors {
		if v.Kind != "replay" {
			continue
		}
		g, ok := byID[v.ID]
		if !ok {
			t.Fatalf("vector %s missing from the TS golden", v.ID)
		}
		t.Run(v.ID, func(t *testing.T) {
			res, err := ReplayV121(chainEventsFromVector(t, v.Events), V121Options{NowMs: v.Options.Now})
			if err != nil {
				t.Fatalf("replay: %v", err)
			}
			if res.EventSetHash != g.EventSetHash {
				t.Errorf("eventSetHash=%s want TS %s", res.EventSetHash, g.EventSetHash)
			}
			if res.BoundaryBlock != g.BoundaryBlock {
				t.Errorf("boundaryBlock=%d want TS %d", res.BoundaryBlock, g.BoundaryBlock)
			}
			if res.TaskComplete != g.TaskComplete {
				t.Errorf("taskComplete=%v want TS %v", res.TaskComplete, g.TaskComplete)
			}
			switch {
			case g.SettlementCanonical == nil && res.Settlement == nil:
				// both no-manifest
			case g.SettlementCanonical == nil:
				t.Errorf("TS produced no manifest, Go did: %s", res.Settlement.Canonical)
			case res.Settlement == nil:
				t.Errorf("TS manifest %s, Go produced none", *g.SettlementCanonical)
			default:
				if string(res.Settlement.Canonical) != *g.SettlementCanonical {
					t.Errorf("settlement manifest bytes diverge:\n go: %s\n ts: %s", res.Settlement.Canonical, *g.SettlementCanonical)
				}
			}
		})
		ran++
	}
	if ran != 14 {
		t.Fatalf("expected 14 replay parity runs, ran %d", ran)
	}
}
